import { Boundary } from "@raf-query/experimental-effect-atom";
import { Match } from "effect";

import { docAtom } from "../src/atoms.ts";
import { useSession } from "../src/boundaries.tsx";

export const Title = (props: { readonly id: number }) => {
	const doc = useSession(docAtom(props.id));
	if (Boundary.isUnhandled(doc)) {
		return (
			<p>
				{Match.valueTags(doc.error, {
					DocNotFound: () => "No such doc",
				})}
			</p>
		);
	}
	return <h1>{doc.title}</h1>;
};

import { Boundary } from "@raf-query/experimental-effect-atom";
import { Match } from "effect";

import { docAtom } from "../src/atoms.ts";
import { useDocAccess } from "../src/boundaries.tsx";

export const Title = (props: { readonly id: number }) => {
	const doc = useDocAccess(docAtom(props.id));
	if (Boundary.isUnhandled(doc)) {
		return (
			<p>
				{Match.valueTags(doc.error, {
					DocNotFound: () => "No such doc",
					Unauthorized: () => "Sign in",
				})}
			</p>
		);
	}
	return <h1>{doc.title}</h1>;
};

import { Boundary } from "@raf-query/experimental-effect-atom";

import { DocAccess } from "../src/boundaries.tsx";

export const [Again, useAgain] = Boundary.catchErrors(DocAccess, {
	fallback: () => <p>Sign in again</p>,
	name: "Again",
	tags: ["DocNotFound", "Unauthorized"],
});

import { Context, Effect } from "effect";

import { DocsClient } from "../src/client.ts";

class Analytics extends Context.Service<
	Analytics,
	{ readonly views: Effect.Effect<number> }
>()("Analytics") {}

export const viewsAtom = DocsClient.runtime.atom(
	Effect.flatMap(Analytics, (analytics) => analytics.views),
);

import { Boundary } from "@raf-query/experimental-effect-atom";

import { renameDocAtom } from "../src/atoms.ts";
import { DocAccess } from "../src/boundaries.tsx";

export const useRenameTo = (id: number) => {
	const rename = Boundary.useSet(DocAccess, renameDocAtom);
	return async (title: string): Promise<string> => {
		const doc = await rename({
			payload: { id, title },
			reactivityKeys: ["docs"],
		});
		return doc.title;
	};
};

import { Boundary } from "@raf-query/experimental-effect-atom";

import { docAtom, docListAtom } from "../src/atoms.ts";
import { DocAccess, useSession } from "../src/boundaries.tsx";

export const [Everything, useEverything] = Boundary.catchErrors(DocAccess, {
	fallback: (props) => <p>Doc {props.error.docId} is gone</p>,
	name: "Everything",
	tags: ["DocNotFound"],
});

export const Title = (props: { readonly id: number }) => {
	const doc = useEverything(docAtom(props.id));
	return <h1>{doc.title}</h1>;
};

export const Titles = () => {
	const docs = useSession(docListAtom);
	return (
		<ul>
			{docs.map((doc) => (
				<li key={doc.id}>{doc.title}</li>
			))}
		</ul>
	);
};

import { Boundary } from "@raf-query/experimental-effect-atom";

import { Session } from "../src/boundaries.tsx";

export const [Access, useAccess] = Boundary.catchErrors(Session, {
	fallback: () => <p>No access</p>,
	name: "Access",
	tags: ["Forbiden"],
